head.script:
scwin.trigger3_onclick = function(e) {
    grid1.setGridHeight(300);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'setGridHeignt'버튼을 클릭한다.
    //1. After running the sample, click the 'setGridHeignt' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 그리드의 높이가 늘어나면서 동일한 row의 데이터가 보여진다.(이전에는 row가 추가되어 보여짐)
    //1. As the height of the grid increases, the data of the same row is shown (previously, the row is added)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid1').style.height == '300px'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_body_tbody tr:nth-child(6)').css('display') == 'none'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.arr = [];
    for (var i = 0; i < 7; i++) {
        arr.push("row_" + i);
        arr.push("data1");
        arr.push("data2");
    }
    grid1.setData(arr);
    grid1.setRowVisible(5, false);
    grid1.setRowVisible(6, false);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 23-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
